        if isinstance(val, (int, float)):
            return float(val)
        if isinstance(val, str):
            # Replace comma with dot for decimal separator
            normalized = val.replace(',', '.')
            try:
                return float(normalized)
            except ValueError:
                return None
        return None

    val_a = parse_value(a)
    val_b = parse_value(b)

